SELECT 
FROM chengke_crm.sys_user
WHERE tenant_id = #{tenantId} AND id = #{userId}

SELECT id, name, code, status, built_in AS builtIn
FROM chengke_crm.sys_role
WHERE tenant_id = #{tenantId} AND id = #{roleId}

mapper.update:
UPDATE chengke_crm.sys_user
SET password_hash = #{passwordHash},
    force_password_change = #{forcePasswordChange},
    updated_at = clock_timestamp(),
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId} AND id = #{userId}

mapper.select:
SELECT fail_count AS failCount, window_started_at AS windowStartedAt, locked_until AS lockedUntil
FROM chengke_crm.auth_login_failure
WHERE account_key = #{accountKey}

UPDATE chengke_crm.auth_captcha
SET consumed_at = #{now}
WHERE token = #{token}
  AND consumed_at IS NULL
  AND expires_at > #{now}
RETURNING code_hash

mapper.update:
UPDATE chengke_crm.auth_session
SET revoked_at = #{now}
WHERE id = #{sessionId} AND revoked_at IS NULL

UPDATE chengke_crm.auth_session
SET revoked_at = #{now}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND revoked_at IS NULL

    AND id <> #{keepSessionId}

mapper.select:
SELECT count(*)
FROM chengke_crm.auth_session
WHERE id = #{sessionId}
  AND revoked_at IS NULL
  AND expires_at > #{now}

SELECT id, tenant_id AS tenantId, user_id AS userId, expires_at AS expiresAt
FROM chengke_crm.auth_session
WHERE id = #{sessionId}
  AND revoked_at IS NULL
  AND expires_at > #{now}

